import math

def is_non_colorful(m):
    # m is non-colorful if 99 * ceil(m / 100) > m
    return 99 * math.ceil(m / 100) > m

# Search for the largest m starting near where we estimate the crossover point (around 100*99 = 9900)
m_max_check = 10000
m = m_max_check
while m >= 100:
    if is_non_colorful(m):
        # Check if the next number is colorful (to ensure this is the largest)
        if not is_non_colorful(m + 1):
            print(f"Largest non-colorful found: {m}")
            break
    m += 1
else:
    print("Reached search limit without finding the largest value, checking initial derivation.")
